# WARNING: Under review - generated by LLM.

import fcntl
import hashlib
import json
import os
import re
import stat
import uuid
from collections.abc import Callable
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from threading import Lock
from typing import Any, TypeVar

from .generation import Message


_SESSION_ID = re.compile(r"[a-f0-9]{32}")
_EVENT_TYPE = re.compile(r"[a-z][a-z0-9_]{0,63}")
_MAX_EVENT_BYTES = 1024 * 1024
_MAX_LOG_BYTES = 16 * 1024 * 1024
_MAX_EVENTS = 100_000
_MAX_INSTRUCTIONS_BYTES = 64 * 1024
_T = TypeVar("_T")


def _json_copy(value: Any) -> Any:
    """Validate and detach the JSON value used by a durable event."""

    try:
        return json.loads(
            json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
        )
    except (TypeError, ValueError) as error:
        raise ValueError("session event data must be JSON serializable") from error


def _read_regular_file(
    path: Path,
    limit: int,
    label: str,
    *,
    dir_fd: int | None = None,
    private: bool = False,
) -> tuple[bytes, tuple[int, int]]:
    """Read a bounded regular file without following a final-component symlink."""

    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags, dir_fd=dir_fd)
    except OSError as error:
        raise ValueError(f"{label} does not exist or is unsafe") from error
    try:
        status = os.fstat(descriptor)
        if (
            not stat.S_ISREG(status.st_mode)
            or status.st_nlink != 1
            or status.st_size > limit
            or (private and stat.S_IMODE(status.st_mode) & 0o077 != 0)
        ):
            raise ValueError(f"{label} is invalid or too large")
        with os.fdopen(descriptor, "rb", closefd=False) as file:
            content = file.read(limit + 1)
        if len(content) > limit:
            raise ValueError(f"{label} is too large")
        return content, (status.st_dev, status.st_ino)
    finally:
        os.close(descriptor)


@dataclass(frozen=True)
class SessionEvent:
    """One immutable event in an append-only agent transcript."""

    id: str
    timestamp: str
    type: str
    parent_id: str | None
    data: dict[str, Any]

    def to_dict(self) -> dict[str, Any]:
        return _json_copy(
            {
                "id": self.id,
                "timestamp": self.timestamp,
                "type": self.type,
                "parent_id": self.parent_id,
                "data": self.data,
            }
        )

    @classmethod
    def from_dict(cls, value: Any) -> "SessionEvent":
        if not isinstance(value, dict) or set(value) != {
            "id",
            "timestamp",
            "type",
            "parent_id",
            "data",
        }:
            raise ValueError("invalid session event fields")
        event_id = value["id"]
        event_type = value["type"]
        parent_id = value["parent_id"]
        if not isinstance(event_id, str) or not _SESSION_ID.fullmatch(event_id):
            raise ValueError("invalid session event ID")
        if not isinstance(event_type, str) or not _EVENT_TYPE.fullmatch(event_type):
            raise ValueError("invalid session event type")
        if parent_id is not None and (
            not isinstance(parent_id, str) or not _SESSION_ID.fullmatch(parent_id)
        ):
            raise ValueError("invalid parent event ID")
        if not isinstance(value["timestamp"], str) or not value["timestamp"]:
            raise ValueError("invalid session event timestamp")
        if not isinstance(value["data"], dict):
            raise ValueError("invalid session event data")
        return cls(
            event_id,
            value["timestamp"],
            event_type,
            parent_id,
            _json_copy(value["data"]),
        )


class SessionLog:
    """A memory-backed or fsync-backed append-only session event stream."""

    def __init__(
        self,
        session_id: str,
        workspace: Path,
        model: str,
        *,
        path: Path | None = None,
        events: tuple[SessionEvent, ...] = (),
        identity: tuple[int, int] | None = None,
        persisted_size: int | None = None,
    ):
        if not _SESSION_ID.fullmatch(session_id):
            raise ValueError("invalid session ID")
        self.session_id = session_id
        self.workspace = workspace.resolve()
        self.model = model
        self.path = path
        self._identity = identity
        self._events = [SessionEvent.from_dict(event.to_dict()) for event in events]
        self._persisted_size = (
            None if path is None else (0 if persisted_size is None else persisted_size)
        )
        self._lock = Lock()
        self._steering_delivery_lock = Lock()
        self._write_failed = False

    @property
    def events(self) -> tuple[SessionEvent, ...]:
        with self._lock:
            return tuple(
                SessionEvent.from_dict(event.to_dict()) for event in self._events
            )

    @property
    def instructions(self) -> tuple[dict[str, str], ...]:
        """Return the newest recorded project-instruction snapshot."""

        snapshot: Any = ()
        for event in self.events:
            if event.type == "session_started":
                snapshot = event.data.get("instructions", ())
            elif event.type == "instructions_changed":
                snapshot = event.data.get("current", ())
        if not isinstance(snapshot, (list, tuple)):
            return ()
        return tuple(item for item in snapshot if isinstance(item, dict))

    def append(
        self, event_type: str, *, parent_id: str | None = None, **data: Any
    ) -> SessionEvent:
        """Append, flush, and fsync before making an event visible in memory."""

        if not _EVENT_TYPE.fullmatch(event_type):
            raise ValueError("invalid session event type")
        with self._lock:
            if self._write_failed:
                raise ValueError("session log is unavailable after a failed append")
            if len(self._events) >= _MAX_EVENTS:
                raise ValueError("session event limit exceeded")
            if not self._events and event_type != "session_started":
                raise ValueError("session_started must be the first event")
            if self._events and event_type == "session_started":
                raise ValueError("session metadata appears more than once")
            if parent_id is None and self._events:
                parent_id = self._events[-1].id
            elif self._events:
                if parent_id != self._events[-1].id:
                    raise ValueError("session event chain is invalid")
            elif not self._events and parent_id is not None:
                if (
                    event_type != "session_started"
                    or data.get("branch_parent_event_id") != parent_id
                    or not isinstance(data.get("branch_parent_session_id"), str)
                ):
                    raise ValueError("session event chain is invalid")
            detached_data = _json_copy(data)
            if event_type == "user_message" and detached_data.get("kind") == "steering":
                source_id = detached_data.get("source_event_id")
                queued = {
                    item.id: item.data.get("content")
                    for item in self._events
                    if item.type == "steering_queued"
                }
                delivered = {
                    item.data.get("source_event_id")
                    for item in self._events
                    if item.type == "user_message"
                    and item.data.get("kind") == "steering"
                }
                if (
                    source_id not in queued
                    or source_id in delivered
                    or detached_data.get("content") != queued[source_id]
                ):
                    raise ValueError(
                        "steering delivery source is invalid or duplicated"
                    )
            if event_type == "tool_result":
                call_id = detached_data.get("tool_call_id")
                if call_id is not None:
                    calls = {
                        item.id for item in self._events if item.type == "tool_call"
                    }
                    completed = {
                        item.data.get("tool_call_id")
                        for item in self._events
                        if item.type == "tool_result"
                    }
                    if call_id not in calls or call_id in completed:
                        raise ValueError("tool result references an invalid call")
                assistant_id = detached_data.get("assistant_event_id")
                if assistant_id is not None:
                    assistants = {
                        item.id
                        for item in self._events
                        if item.type == "assistant_message"
                    }
                    dispositions = {
                        item.data.get("assistant_event_id")
                        for item in self._events
                        if item.type == "tool_result"
                    }
                    if (
                        call_id is not None
                        or assistant_id not in assistants
                        or assistant_id in dispositions
                    ):
                        raise ValueError(
                            "assistant disposition reference is invalid or duplicated"
                        )
            if event_type == "command_started":
                command_id = detached_data.get("command_id")
                argv = detached_data.get("argv")
                started_commands = {
                    item.data.get("command_id")
                    for item in self._events
                    if item.type == "command_started"
                }
                if (
                    not isinstance(command_id, str)
                    or _SESSION_ID.fullmatch(command_id) is None
                    or command_id in started_commands
                    or not isinstance(argv, list)
                    or not argv
                    or any(
                        not isinstance(argument, str) or not argument
                        for argument in argv
                    )
                ):
                    raise ValueError("command start event is invalid")
            if event_type == "command_finished":
                command_id = detached_data.get("command_id")
                started_commands = {
                    item.data.get("command_id")
                    for item in self._events
                    if item.type == "command_started"
                }
                finished_commands = {
                    item.data.get("command_id")
                    for item in self._events
                    if item.type == "command_finished"
                }
                returncode = detached_data.get("returncode")
                launched = detached_data.get("launched")
                cleanup_incomplete = detached_data.get("cleanup_incomplete")
                if (
                    command_id not in started_commands
                    or command_id in finished_commands
                    or isinstance(returncode, bool)
                    or not isinstance(returncode, int)
                    or not isinstance(launched, bool)
                    or not isinstance(cleanup_incomplete, bool)
                ):
                    raise ValueError("command finish event is invalid")
            event = SessionEvent(
                uuid.uuid4().hex,
                datetime.now(timezone.utc).isoformat(),
                event_type,
                parent_id,
                detached_data,
            )
            encoded = (
                json.dumps(
                    event.to_dict(),
                    ensure_ascii=True,
                    sort_keys=True,
                    separators=(",", ":"),
                )
                + "\n"
            ).encode("utf-8")
            if len(encoded) > _MAX_EVENT_BYTES:
                raise ValueError("session event is too large")
            if self.path is not None:
                flags = os.O_RDWR | os.O_APPEND | getattr(os, "O_NOFOLLOW", 0)
                descriptor = os.open(self.path, flags)
                original_size = None
                try:
                    fcntl.flock(descriptor, fcntl.LOCK_EX)
                    status = os.fstat(descriptor)
                    if (
                        not stat.S_ISREG(status.st_mode)
                        or status.st_nlink != 1
                        or stat.S_IMODE(status.st_mode) & 0o077 != 0
                        or self._identity != (status.st_dev, status.st_ino)
                        or self._persisted_size != status.st_size
                        or status.st_size + len(encoded) > _MAX_LOG_BYTES
                    ):
                        raise ValueError("session file changed or is invalid")
                    self._validate_persisted_head(descriptor, status.st_size)
                    original_size = status.st_size
                    written = 0
                    while written < len(encoded):
                        count = os.write(descriptor, encoded[written:])
                        if count <= 0:
                            raise OSError("session append made no progress")
                        written += count
                    os.fsync(descriptor)
                    self._events.append(event)
                    self._persisted_size = original_size + len(encoded)
                except BaseException:
                    event_published = bool(
                        self._events and self._events[-1].id == event.id
                    )
                    if event_published:
                        if original_size is not None:
                            self._persisted_size = original_size + len(encoded)
                    else:
                        try:
                            if original_size is not None:
                                os.ftruncate(descriptor, original_size)
                                os.fsync(descriptor)
                                self._persisted_size = original_size
                        except BaseException:
                            self._write_failed = True
                    raise
                finally:
                    try:
                        fcntl.flock(descriptor, fcntl.LOCK_UN)
                    except OSError:
                        pass
                    os.close(descriptor)
            else:
                self._events.append(event)
            return SessionEvent.from_dict(event.to_dict())

    def _validate_persisted_head(self, descriptor: int, size: int) -> None:
        """Reject a stale in-memory head before appending another child event."""

        expected_id = self._events[-1].id if self._events else None
        if size == 0:
            if expected_id is not None:
                raise ValueError("session persisted head is missing")
            return
        window = min(size, _MAX_EVENT_BYTES)
        tail = os.pread(descriptor, window, size - window)
        if len(tail) != window or not tail.endswith(b"\n"):
            raise ValueError("session persisted tail is invalid")
        try:
            persisted = SessionEvent.from_dict(json.loads(tail.splitlines()[-1]))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise ValueError("session persisted tail is invalid") from error
        if persisted.id != expected_id:
            raise ValueError("session persisted head changed")

    def messages(self, system_prompt: str) -> list[Message]:
        """Rebuild semantic model messages without exposing audit-only events."""

        blocks = [item.get("content", "") for item in self.instructions]
        blocks = [block for block in blocks if isinstance(block, str) and block]
        if blocks:
            system_prompt += "\n\nProject instructions:\n" + "\n\n".join(blocks)
        messages: list[Message] = [{"role": "system", "content": system_prompt}]
        for event in self.events:
            content = event.data.get("content")
            if event.type == "user_message" and isinstance(content, str):
                messages.append({"role": "user", "content": content})
            elif event.type == "assistant_message" and isinstance(content, str):
                messages.append({"role": "assistant", "content": content})
            elif event.type == "tool_result" and isinstance(content, str):
                messages.append({"role": "user", "content": f"Tool result:\n{content}"})
        return messages

    def pending_steering(self) -> tuple[SessionEvent, ...]:
        """Return queued corrections not yet materialized at a turn boundary."""

        events = self.events
        queued = {
            event.id: event for event in events if event.type == "steering_queued"
        }
        delivered: set[str] = set()
        for event in events:
            if event.type != "user_message" or event.data.get("kind") != "steering":
                continue
            source_id = event.data.get("source_event_id")
            if not isinstance(source_id, str) or source_id not in queued:
                raise ValueError("delivered steering references an invalid queue event")
            if source_id in delivered:
                raise ValueError("steering queue event was delivered more than once")
            delivered.add(source_id)
        return tuple(
            event for event_id, event in queued.items() if event_id not in delivered
        )

    def queue_steering(self, message: str) -> SessionEvent:
        """Linearize a durable steering submission with terminal acceptance."""

        if not isinstance(message, str) or not message.strip():
            raise ValueError("steering message must not be blank")
        with self._steering_delivery_lock:
            return self.append("steering_queued", content=message)

    def run_if_no_pending_steering(
        self, operation: Callable[[], _T]
    ) -> tuple[bool, _T | None]:
        """Run one terminal operation only if queued steering did not win."""

        with self._steering_delivery_lock:
            if self.pending_steering():
                return False, None
            return True, operation()

    def deliver_pending_steering(self) -> tuple[SessionEvent, ...]:
        """Append queued corrections as semantic messages at a safe boundary."""

        with self._steering_delivery_lock:
            delivered = []
            for event in self.pending_steering():
                content = event.data.get("content")
                if not isinstance(content, str) or not content.strip():
                    raise ValueError("queued steering message is invalid")
                delivered.append(
                    self.append(
                        "user_message",
                        content=content,
                        kind="steering",
                        source_event_id=event.id,
                    )
                )
            return tuple(delivered)

    def recover_unmatched_tool_calls(self) -> tuple[SessionEvent, ...]:
        """Record interruption observations without repeating an uncertain call."""

        events = self.events
        matched = {
            event.data.get("tool_call_id")
            for event in events
            if event.type == "tool_result"
        }
        recovered = []
        for event in events:
            if event.type == "tool_call" and event.id not in matched:
                recovered.append(
                    self.append(
                        "tool_result",
                        tool_call_id=event.id,
                        tool=event.data.get("tool"),
                        is_error=True,
                        content=(
                            "error: the prior process stopped before this tool call "
                            "recorded a result; it was not repeated"
                        ),
                    )
                )
        return tuple(recovered)

    def recover_incomplete_turns(self) -> tuple[SessionEvent, ...]:
        """Close crash gaps after a durable response without interpreting it."""

        recovered = list(self.recover_unmatched_tool_calls())
        events = self.events
        protocol_events = {
            "assistant_message",
            "tool_call",
            "tool_result",
            "run_finished",
            "run_started",
            "user_message",
        }
        for index, event in enumerate(events):
            if event.type != "assistant_message":
                continue
            if any(
                candidate.type == "tool_result"
                and candidate.data.get("assistant_event_id") == event.id
                for candidate in events[index + 1 :]
            ):
                continue
            following = next(
                (
                    candidate
                    for candidate in events[index + 1 :]
                    if candidate.type in protocol_events
                ),
                None,
            )
            if (
                following is None
                or following.type
                in {
                    "assistant_message",
                    "run_started",
                    "user_message",
                }
                or (
                    following.type == "run_finished"
                    and following.data.get("completed") is not True
                )
            ):
                recovered.append(
                    self.append(
                        "tool_result",
                        tool_call_id=None,
                        tool=None,
                        is_error=True,
                        assistant_event_id=event.id,
                        content=(
                            "error: the prior process stopped after recording a "
                            "model response; no action from it was repeated"
                        ),
                    )
                )
        return tuple(recovered)


class SessionStore:
    """Create and resume workspace-bound local session transcripts."""

    def __init__(
        self,
        workspace: Path,
        model: str,
        *,
        expected_workspace_identity: tuple[int, int] | None = None,
    ):
        self.workspace = workspace.resolve()
        self.model = model
        self.directory = self.workspace / ".tiny-llm" / "sessions"
        self._expected_workspace_identity = expected_workspace_identity

    def _validate_workspace_identity(self, descriptor: int) -> None:
        """Reject a workspace pathname rebound before a session-side effect."""

        if self._expected_workspace_identity is None:
            return
        status = os.fstat(descriptor)
        if (status.st_dev, status.st_ino) != self._expected_workspace_identity:
            raise ValueError("session workspace identity changed")

    def _ensure_directory(self) -> None:
        descriptor = self._open_directory(create=True)
        os.close(descriptor)

    def _open_directory(self, *, create: bool) -> int:
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        root = os.open(self.workspace, flags)
        parent = None
        try:
            self._validate_workspace_identity(root)
            parent_created = False
            if create:
                try:
                    os.mkdir(".tiny-llm", 0o700, dir_fd=root)
                    parent_created = True
                except FileExistsError:
                    pass
            if parent_created:
                os.fsync(root)
            parent = os.open(".tiny-llm", flags, dir_fd=root)
            if not stat.S_ISDIR(os.fstat(parent).st_mode):
                raise ValueError("session path is unsafe")
            os.fchmod(parent, 0o700)
            directory_created = False
            if create:
                try:
                    os.mkdir("sessions", 0o700, dir_fd=parent)
                    directory_created = True
                except FileExistsError:
                    pass
            if directory_created:
                os.fsync(parent)
            directory = os.open("sessions", flags, dir_fd=parent)
            if not stat.S_ISDIR(os.fstat(directory).st_mode):
                os.close(directory)
                raise ValueError("session path is unsafe")
            os.fchmod(directory, 0o700)
            return directory
        except OSError as error:
            raise ValueError("session path is unsafe") from error
        finally:
            if parent is not None:
                os.close(parent)
            os.close(root)

    def _fsync_directory(self, descriptor: int | None = None) -> None:
        owned = descriptor is None
        if descriptor is None:
            descriptor = self._open_directory(create=False)
        try:
            os.fsync(descriptor)
        finally:
            if owned:
                os.close(descriptor)

    def _instructions(self) -> tuple[dict[str, str], ...]:
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        root = os.open(self.workspace, flags)
        try:
            self._validate_workspace_identity(root)
            try:
                content, _ = _read_regular_file(
                    Path("AGENTS.md"),
                    _MAX_INSTRUCTIONS_BYTES,
                    "AGENTS.md",
                    dir_fd=root,
                )
            except ValueError as error:
                try:
                    os.stat("AGENTS.md", dir_fd=root, follow_symlinks=False)
                except FileNotFoundError:
                    return ()
                raise error
        finally:
            os.close(root)
        text = content.decode("utf-8")
        return (
            {
                "path": "AGENTS.md",
                "sha256": hashlib.sha256(content).hexdigest(),
                "content": text,
            },
        )

    def create(self, session_id: str | None = None) -> SessionLog:
        return self._create_session(session_id)

    def _create_session(
        self,
        session_id: str | None,
        *,
        branch_parent_session_id: str | None = None,
        branch_parent_event_id: str | None = None,
    ) -> SessionLog:
        instructions = self._instructions()
        session_id = session_id or uuid.uuid4().hex
        if not _SESSION_ID.fullmatch(session_id):
            raise ValueError("invalid session ID")
        directory = self._open_directory(create=True)
        path = self.directory / f"{session_id}.jsonl"
        temporary = self.directory / f".{session_id}-{uuid.uuid4().hex}.tmp"
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(temporary.name, flags, 0o600, dir_fd=directory)
        except BaseException:
            os.close(directory)
            raise
        status = os.fstat(descriptor)
        os.close(descriptor)
        log = SessionLog(
            session_id,
            self.workspace,
            self.model,
            path=temporary,
            identity=(status.st_dev, status.st_ino),
        )
        linked = False
        try:
            metadata: dict[str, Any] = {
                "session_id": session_id,
                "workspace": str(self.workspace),
                "model": self.model,
                "instructions": instructions,
            }
            if branch_parent_event_id is not None:
                metadata.update(
                    branch_id=session_id,
                    branch_parent_session_id=branch_parent_session_id,
                    branch_parent_event_id=branch_parent_event_id,
                )
            log.append(
                "session_started",
                parent_id=branch_parent_event_id,
                **metadata,
            )
            os.link(
                temporary.name,
                path.name,
                src_dir_fd=directory,
                dst_dir_fd=directory,
                follow_symlinks=False,
            )
            linked = True
            os.unlink(temporary.name, dir_fd=directory)
            log.path = path
            self._fsync_directory(directory)
        except BaseException:
            try:
                os.unlink(temporary.name, dir_fd=directory)
            except FileNotFoundError:
                pass
            if linked:
                try:
                    os.unlink(path.name, dir_fd=directory)
                except FileNotFoundError:
                    pass
            self._fsync_directory(directory)
            raise
        finally:
            os.close(directory)
        return log

    @staticmethod
    def _validate_events(events: list[SessionEvent]) -> None:
        if not events or events[0].type != "session_started":
            raise ValueError("session metadata is missing")
        external_parent = events[0].data.get("branch_parent_event_id")
        external_session = events[0].data.get("branch_parent_session_id")
        if events[0].parent_id is None and (
            external_parent is not None or external_session is not None
        ):
            raise ValueError("session branch metadata is invalid")
        if events[0].parent_id is not None and (
            events[0].parent_id != external_parent
            or not isinstance(external_session, str)
            or not _SESSION_ID.fullmatch(external_session)
            or not isinstance(external_parent, str)
            or not _SESSION_ID.fullmatch(external_parent)
        ):
            raise ValueError("session event chain is invalid")
        calls: set[str] = set()
        results: set[str] = set()
        queued_steering: dict[str, object] = {}
        delivered_steering: set[str] = set()
        assistants: set[str] = set()
        assistant_dispositions: set[str] = set()
        commands: set[str] = set()
        command_results: set[str] = set()
        for index, event in enumerate(events):
            if index and event.type == "session_started":
                raise ValueError("session metadata appears more than once")
            if index and event.parent_id != events[index - 1].id:
                raise ValueError("session event chain is invalid")
            if event.type == "tool_call":
                calls.add(event.id)
            elif event.type == "steering_queued":
                queued_steering[event.id] = event.data.get("content")
            elif event.type == "user_message" and event.data.get("kind") == "steering":
                source_id = event.data.get("source_event_id")
                if (
                    source_id not in queued_steering
                    or source_id in delivered_steering
                    or event.data.get("content") != queued_steering[source_id]
                ):
                    raise ValueError(
                        "steering delivery source is invalid or duplicated"
                    )
                delivered_steering.add(source_id)
            elif event.type == "assistant_message":
                assistants.add(event.id)
            if event.type == "tool_result":
                call_id = event.data.get("tool_call_id")
                if call_id is not None:
                    if call_id not in calls or call_id in results:
                        raise ValueError("tool result references an invalid call")
                    results.add(call_id)
                assistant_id = event.data.get("assistant_event_id")
                if assistant_id is not None:
                    if (
                        call_id is not None
                        or assistant_id not in assistants
                        or assistant_id in assistant_dispositions
                    ):
                        raise ValueError(
                            "assistant disposition reference is invalid or duplicated"
                        )
                    assistant_dispositions.add(assistant_id)
            if event.type == "command_started":
                command_id = event.data.get("command_id")
                argv = event.data.get("argv")
                if (
                    not isinstance(command_id, str)
                    or _SESSION_ID.fullmatch(command_id) is None
                    or command_id in commands
                    or not isinstance(argv, list)
                    or not argv
                    or any(
                        not isinstance(argument, str) or not argument
                        for argument in argv
                    )
                ):
                    raise ValueError("command start event is invalid")
                commands.add(command_id)
            elif event.type == "command_finished":
                command_id = event.data.get("command_id")
                returncode = event.data.get("returncode")
                launched = event.data.get("launched")
                cleanup_incomplete = event.data.get("cleanup_incomplete")
                if (
                    command_id not in commands
                    or command_id in command_results
                    or isinstance(returncode, bool)
                    or not isinstance(returncode, int)
                    or not isinstance(launched, bool)
                    or not isinstance(cleanup_incomplete, bool)
                ):
                    raise ValueError("command finish event is invalid")
                command_results.add(command_id)

    def _recover_publication(self, directory: int, name: str) -> None:
        """Finish the link publication if a crash left its private name."""

        try:
            status = os.stat(name, dir_fd=directory, follow_symlinks=False)
        except FileNotFoundError as error:
            raise ValueError("session file does not exist or is unsafe") from error
        if status.st_nlink == 1:
            return
        prefix = f".{Path(name).stem}-"
        matches = []
        for candidate in os.listdir(directory):
            if not candidate.startswith(prefix) or not candidate.endswith(".tmp"):
                continue
            candidate_status = os.stat(
                candidate, dir_fd=directory, follow_symlinks=False
            )
            if (candidate_status.st_dev, candidate_status.st_ino) == (
                status.st_dev,
                status.st_ino,
            ):
                matches.append(candidate)
        if status.st_nlink != 2 or len(matches) != 1:
            raise ValueError("session file has an unsafe link count")
        os.unlink(matches[0], dir_fd=directory)
        os.fsync(directory)

    def _truncate_partial_tail(
        self,
        path: Path,
        expected_content: bytes,
        complete_size: int,
        identity: tuple[int, int],
    ) -> None:
        """Discard only a verified incomplete final append from a private log."""

        if complete_size <= 0 or complete_size >= len(expected_content):
            raise ValueError("session partial-tail boundary is invalid")
        directory = self._open_directory(create=False)
        descriptor = None
        try:
            descriptor = os.open(
                path.name,
                os.O_RDWR | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=directory,
            )
            fcntl.flock(descriptor, fcntl.LOCK_EX)
            status = os.fstat(descriptor)
            if (
                not stat.S_ISREG(status.st_mode)
                or status.st_nlink != 1
                or stat.S_IMODE(status.st_mode) & 0o077 != 0
                or (status.st_dev, status.st_ino) != identity
                or status.st_size != len(expected_content)
            ):
                raise ValueError("session changed during partial-tail recovery")
            os.lseek(descriptor, 0, os.SEEK_SET)
            current = bytearray()
            while len(current) < len(expected_content):
                chunk = os.read(descriptor, len(expected_content) - len(current))
                if not chunk:
                    break
                current.extend(chunk)
            if bytes(current) != expected_content:
                raise ValueError("session changed during partial-tail recovery")
            os.ftruncate(descriptor, complete_size)
            os.fsync(descriptor)
            os.fsync(directory)
        finally:
            if descriptor is not None:
                try:
                    fcntl.flock(descriptor, fcntl.LOCK_UN)
                except OSError:
                    pass
                os.close(descriptor)
            os.close(directory)

    def load(self, session_id: str, *, recover: bool = True) -> SessionLog:
        if not _SESSION_ID.fullmatch(session_id):
            raise ValueError("invalid session ID")
        path = self.directory / f"{session_id}.jsonl"
        directory = self._open_directory(create=False)
        try:
            self._recover_publication(directory, path.name)
            content, identity = _read_regular_file(
                Path(path.name),
                _MAX_LOG_BYTES,
                "session file",
                dir_fd=directory,
                private=True,
            )
        finally:
            os.close(directory)
        partial_tail = bool(content and not content.endswith(b"\n"))
        if partial_tail and not recover:
            raise ValueError("session file ends with a partial event")
        complete_size = len(content)
        parse_content = content
        if partial_tail:
            complete_size = content.rfind(b"\n") + 1
            if complete_size <= 0:
                raise ValueError("session metadata ends with a partial event")
            parse_content = content[:complete_size]
        events = []
        seen = set()
        for number, line in enumerate(parse_content.splitlines(), 1):
            if number > _MAX_EVENTS or len(line) > _MAX_EVENT_BYTES:
                raise ValueError("session event limit exceeded")
            try:
                event = SessionEvent.from_dict(json.loads(line))
            except (UnicodeDecodeError, json.JSONDecodeError) as error:
                raise ValueError(f"invalid session JSONL line {number}") from error
            if event.id in seen:
                raise ValueError("duplicate session event ID")
            seen.add(event.id)
            events.append(event)
        self._validate_events(events)
        metadata = events[0].data
        if metadata.get("branch_parent_event_id") is not None:
            completed = [event for event in events if event.type == "branch_completed"]
            if len(completed) != 1:
                raise ValueError("session branch is incomplete")
        if metadata.get("session_id") != session_id:
            raise ValueError("session metadata ID does not match its filename")
        if metadata.get("workspace") != str(self.workspace):
            raise ValueError("session belongs to a different workspace")
        if metadata.get("model") != self.model:
            raise ValueError("session belongs to a different model")
        if partial_tail:
            self._truncate_partial_tail(path, content, complete_size, identity)
        log = SessionLog(
            session_id,
            self.workspace,
            self.model,
            path=path,
            events=tuple(events),
            identity=identity,
            persisted_size=complete_size,
        )
        if recover:
            if partial_tail:
                log.append(
                    "session_tail_recovered",
                    discarded_bytes=len(content) - complete_size,
                )
            current = self._instructions()
            if current != log.instructions:
                log.append(
                    "instructions_changed", previous=log.instructions, current=current
                )
            log.recover_incomplete_turns()
        return log

    def branch(
        self,
        session_id: str,
        at_event_id: str,
        new_session_id: str | None = None,
    ) -> SessionLog:
        """Create a private lineage with model context ending at one ancestor."""

        parent = self.load(session_id, recover=False)
        parent_events = parent.events
        self._validate_branch_side_effect_state(parent_events)
        selected_index = next(
            (
                index
                for index, event in enumerate(parent_events)
                if event.id == at_event_id
            ),
            None,
        )
        if selected_index is None or selected_index == 0:
            raise ValueError("branch ancestor is not present in the parent session")
        prefix = parent_events[: selected_index + 1]
        calls = {event.id for event in prefix if event.type == "tool_call"}
        results = {
            event.data.get("tool_call_id")
            for event in prefix
            if event.type == "tool_result"
        }
        if calls - results or prefix[-1].type in {
            "assistant_message",
            "mutation_intent",
            "summary_attempt",
            "tool_call",
        }:
            raise ValueError("branch ancestor does not close a safe event boundary")

        branch = self._create_session(
            new_session_id,
            branch_parent_session_id=parent.session_id,
            branch_parent_event_id=at_event_id,
        )
        branch.append(
            "branch_created",
            parent_session_id=parent.session_id,
            at_event_id=at_event_id,
            source_event_count=len(prefix),
        )
        copied_types = {
            "assistant_message",
            "run_finished",
            "run_started",
            "steering_queued",
            "tool_call",
            "tool_result",
            "user_message",
        }
        copied_ids: dict[str, str] = {}
        for event in prefix[1:]:
            if event.type not in copied_types:
                continue
            data = _json_copy(event.data)
            if event.type == "tool_result":
                source_call_id = data.get("tool_call_id")
                if source_call_id is not None:
                    if source_call_id not in copied_ids:
                        raise ValueError(
                            "branch prefix contains an invalid tool result"
                        )
                    data["tool_call_id"] = copied_ids[source_call_id]
                source_assistant_id = data.get("assistant_event_id")
                if source_assistant_id is not None:
                    if source_assistant_id not in copied_ids:
                        raise ValueError(
                            "branch prefix contains an invalid assistant disposition"
                        )
                    data["assistant_event_id"] = copied_ids[source_assistant_id]
            if event.type == "user_message" and data.get("kind") == "steering":
                source_steering_id = data.get("source_event_id")
                if source_steering_id not in copied_ids:
                    raise ValueError("branch prefix contains invalid steering")
                data["source_parent_steering_event_id"] = source_steering_id
                data["source_event_id"] = copied_ids[source_steering_id]
            data["source_parent_event_id"] = event.id
            copied = branch.append(event.type, **data)
            copied_ids[event.id] = copied.id
        branch.append(
            "branch_completed",
            parent_session_id=parent.session_id,
            at_event_id=at_event_id,
            copied_event_count=len(copied_ids),
        )
        return branch

    @staticmethod
    def _validate_branch_side_effect_state(
        events: tuple[SessionEvent, ...],
    ) -> None:
        """Reject a branch while shared-workspace side effects are unresolved."""

        calls: set[str] = set()
        call_results: set[str] = set()
        mutations: set[str] = set()
        mutation_results: set[str] = set()
        undo_changes: set[str] = set()
        undo_results: set[str] = set()
        commands: set[str] = set()
        command_results: set[str] = set()
        conflicts = False
        malformed = False

        def valid_id(value: object) -> bool:
            return isinstance(value, str) and _SESSION_ID.fullmatch(value) is not None

        for event in events:
            data = event.data
            if event.type == "tool_call":
                calls.add(event.id)
            elif event.type == "tool_result":
                call_id = data.get("tool_call_id")
                if isinstance(call_id, str):
                    call_results.add(call_id)
            elif event.type == "mutation_intent":
                intent_id = data.get("intent_id")
                if valid_id(intent_id) and intent_id not in mutations:
                    mutations.add(intent_id)
                else:
                    malformed = True
            elif event.type in {"mutation_committed", "mutation_recovered"}:
                intent_id = data.get("intent_id")
                if (
                    valid_id(intent_id)
                    and intent_id in mutations
                    and intent_id not in mutation_results
                ):
                    mutation_results.add(intent_id)
                else:
                    malformed = True
                if event.type == "mutation_recovered":
                    if data.get("status") == "conflict":
                        conflicts = True
                    elif data.get("status") != "not_applied":
                        malformed = True
            elif event.type == "undo_change_started":
                change_id = data.get("undo_change_id")
                if valid_id(change_id) and change_id not in undo_changes:
                    undo_changes.add(change_id)
                else:
                    malformed = True
            elif event.type in {"undo_change_finished", "undo_change_recovered"}:
                change_id = data.get("undo_change_id")
                if (
                    valid_id(change_id)
                    and change_id in undo_changes
                    and change_id not in undo_results
                ):
                    undo_results.add(change_id)
                else:
                    malformed = True
                if event.type == "undo_change_recovered":
                    if data.get("status") == "conflict":
                        conflicts = True
                    elif data.get("status") != "not_applied":
                        malformed = True
            elif event.type == "undo_completed":
                recorded_conflicts = data.get("conflicts")
                if not isinstance(recorded_conflicts, list):
                    malformed = True
                elif recorded_conflicts:
                    conflicts = True
            elif event.type == "command_started":
                command_id = data.get("command_id")
                if valid_id(command_id) and command_id not in commands:
                    commands.add(command_id)
                else:
                    malformed = True
            elif event.type == "command_finished":
                command_id = data.get("command_id")
                if (
                    valid_id(command_id)
                    and command_id in commands
                    and command_id not in command_results
                ):
                    command_results.add(command_id)
                else:
                    malformed = True
                if not isinstance(data.get("launched"), bool) or not isinstance(
                    data.get("cleanup_incomplete"), bool
                ):
                    malformed = True
                elif data["cleanup_incomplete"]:
                    conflicts = True
        if (
            malformed
            or conflicts
            or calls - call_results
            or mutations - mutation_results
            or mutation_results - mutations
            or undo_changes - undo_results
            or undo_results - undo_changes
            or commands - command_results
            or command_results - commands
        ):
            raise ValueError(
                "parent session has unresolved or conflicting workspace side effects"
            )

    def latest(self) -> SessionLog:
        directory = self._open_directory(create=False)
        try:
            candidates = []
            for name in os.listdir(directory):
                path = Path(name)
                if path.suffix != ".jsonl" or not _SESSION_ID.fullmatch(path.stem):
                    continue
                status = os.stat(name, dir_fd=directory, follow_symlinks=False)
                if stat.S_ISREG(status.st_mode):
                    candidates.append((status.st_mtime_ns, name))
            candidates.sort(reverse=True)
            if not candidates:
                raise ValueError("no saved session exists")
            for _, name in candidates:
                self._recover_publication(directory, name)
                content, _ = _read_regular_file(
                    Path(name),
                    _MAX_LOG_BYTES,
                    "session file",
                    dir_fd=directory,
                    private=True,
                )
                first_line = content.splitlines()[:1]
                if not first_line:
                    raise ValueError("session metadata is missing")
                try:
                    metadata = SessionEvent.from_dict(json.loads(first_line[0]))
                except (UnicodeDecodeError, json.JSONDecodeError) as error:
                    raise ValueError("invalid session metadata") from error
                if metadata.type != "session_started":
                    raise ValueError("session metadata is missing")
                if metadata.data.get("session_id") != Path(name).stem:
                    raise ValueError("session metadata ID does not match its filename")
                if metadata.data.get("workspace") != str(self.workspace):
                    raise ValueError("session belongs to a different workspace")
                if metadata.data.get("model") == self.model:
                    if metadata.data.get("branch_parent_event_id") is not None:
                        if content and not content.endswith(b"\n"):
                            continue
                        try:
                            branch_complete = any(
                                SessionEvent.from_dict(json.loads(line)).type
                                == "branch_completed"
                                for line in content.splitlines()[1:]
                            )
                        except (
                            UnicodeDecodeError,
                            json.JSONDecodeError,
                            ValueError,
                        ):
                            continue
                        if not branch_complete:
                            continue
                    selected = Path(name).stem
                    break
            else:
                raise ValueError("no saved session exists for this model")
        finally:
            os.close(directory)
        return self.load(selected)


def memory_session(workspace: Path, model: str) -> SessionLog:
    """Create an event log that never writes a transcript to disk."""

    store = SessionStore(workspace, model)
    log = SessionLog(uuid.uuid4().hex, store.workspace, model)
    log.append(
        "session_started",
        session_id=log.session_id,
        workspace=str(store.workspace),
        model=model,
        instructions=store._instructions(),
    )
    return log
